#include "ui.h"



///////////////////// LVGL SETTINGS ////////////////////
#if LV_COLOR_DEPTH != 16
#error "LV_COLOR_DEPTH should be 16bit to match project settings"
#endif

///////////////////// VARIABLES ////////////////////
static bool ui_initialized = false;
/* 全局对象句柄的唯一实例；各屏幕的创建代码负责填写字段，删除回调负责清空。 */
aidogui_ui_t aidogui_ui = {0};

int aidogui_get_screen_width(void)
{
    return SCREEN_WIDTH;
}

int aidogui_get_screen_height(void)
{
    return SCREEN_HEIGHT;
}

///////////////////// SCREENS ////////////////////
/* 直接实现公开入口，初始化和销毁逻辑不经旧名称包装。 */
void aidogui_init(void)
{
    if (ui_initialized) return;
    if (lv_disp_get_default() == NULL) {
        LV_LOG_ERROR("Create an LVGL display before aidogui_init");
        return;
    }
#if LV_USE_THEME_DEFAULT
    /* 与设计器的默认浅色主题一致；不能改用简单主题，否则未显式配置的控件样式会丢失。 */
    lv_disp_set_theme(lv_disp_get_default(), lv_theme_default_init(
        lv_disp_get_default(), lv_palette_main(LV_PALETTE_BLUE),
        lv_palette_main(LV_PALETTE_AMBER), false, LV_FONT_DEFAULT));
#endif
    /* 字体就绪后再创建控件，避免样式引用未加载的 BIN 字体。 */
    if (!aidogui_fonts_init()) {
        return;
    }
    LV_EVENT_GET_COMP_CHILD = lv_event_register_id();
    ui_initialized = true;
    /* 创建全部屏幕，不只创建默认屏幕；各屏幕入口会跳过仍有效的已有对象。 */
    ui_launcher_screen_init();
    ui_clock_screen_init();
    ui_weather_screen_init();
    ui_music_screen_init();
    ui_album_screen_init();
    ui_settings_screen_init();
    /* 执行工程配置的初始化动作，再加载默认屏幕。 */
    lv_scr_load(aidogui_ui.launcher.root);
    _ui_release_fallback_screen();
    //initialize the custom code
    custom_init(&aidogui_ui);
}

void aidogui_destroy(void)
{
    if (!ui_initialized) return;
    /* 先销毁屏幕，最后释放字体。 */
    ui_launcher_screen_destroy();
    ui_clock_screen_destroy();
    ui_weather_screen_destroy();
    ui_music_screen_destroy();
    ui_album_screen_destroy();
    ui_settings_screen_destroy();
    aidogui_fonts_destroy();
    ui_initialized = false;
}
